// Find NYC home-service businesses with great reviews but NO website.
// Replace the API key below, or store it in n8n credentials and reference it.
const API_KEY = 'PASTE_YOUR_PLACES_API_KEY_HERE';
const MIN_RATING = 4.3;
const MIN_REVIEWS = 15;

// Trade -> Google Maps searches. Add/trim neighborhoods or trades as you like.
const TRADES = {
  'Pest Control': [
    'exterminator Astoria Queens NY', 'pest control Flushing Queens NY',
    'exterminator Jamaica Queens NY', 'pest control Bay Ridge Brooklyn NY',
    'exterminator Bushwick Brooklyn NY', 'pest control Flatbush Brooklyn NY',
    'exterminator Fordham Bronx NY', 'pest control Staten Island NY',
  ],
  'Plumber': [
    'plumber Astoria Queens NY', 'plumber Flushing Queens NY',
    'plumber Bay Ridge Brooklyn NY', 'plumber Fordham Bronx NY',
  ],
};

const FIELD_MASK = 'places.id,places.displayName,places.rating,places.userRatingCount,places.websiteUri,places.nationalPhoneNumber,places.formattedAddress,places.googleMapsUri';
const SOCIAL = ['facebook.com', 'instagram.com', 'yelp.com', 'linktr', 'business.site'];
const today = new Date().toISOString().slice(0, 10);
const seen = new Set();
const rows = [];

for (const trade of Object.keys(TRADES)) {
  for (const query of TRADES[trade]) {
    let res;
    try {
      res = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://places.googleapis.com/v1/places:searchText',
        headers: {
          'Content-Type': 'application/json',
          'X-Goog-Api-Key': API_KEY,
          'X-Goog-FieldMask': FIELD_MASK,
        },
        body: { textQuery: query, pageSize: 20 },
        json: true,
      });
    } catch (e) { continue; }

    const area = query.replace(/^(exterminator|pest control|plumber|electrician)\s/i, '').replace(/\sNY$/i, '');
    for (const p of (res.places || [])) {
      if (!p.id || seen.has(p.id)) continue;
      const rating = p.rating || 0;
      const reviews = p.userRatingCount || 0;
      const uri = (p.websiteUri || '').toLowerCase();
      const social = SOCIAL.some((s) => uri.includes(s));
      const hasSite = uri && !social;
      if (rating < MIN_RATING || reviews < MIN_REVIEWS || hasSite) continue;
      seen.add(p.id);
      rows.push({ json: {
        Business: (p.displayName && p.displayName.text) || '',
        Trade: trade,
        Area: area,
        Rating: rating,
        Reviews: reviews,
        Website: uri ? (social ? 'Social only' : 'Has site') : 'None',
        Phone: p.nationalPhoneNumber || '',
        Address: p.formattedAddress || '',
        Maps: p.googleMapsUri || '',
        Status: 'New',
        Found: today,
      }});
    }
  }
}

return rows;
